using System.Linq;
using System;
using System.IO;
using UnityEditor;
using UnityEngine;

namespace RebirthEntityStudio {
 // Development artifact generator, deliberately excluded from the installed tool.
 public static class RebirthFaceImageExample {
  static RebirthFaceImageJob job;static FaceTemplate template;static DateTime started;
  public static void Generate(){try{
   template=RebirthFaceGeneratorWindow.ReadTemplate();var image=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/FaceImageExample.png");job=new RebirthFaceImageJob(template,FaceRecipe.FromPreset(template,0),image);started=DateTime.UtcNow;EditorApplication.update+=Poll;
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  public static void PrepareSavedLining(){try{var data=RebirthFaceGeneratorWindow.ReadTemplate();string output=Environment.GetEnvironmentVariable("REBIRTH_FACE_IMAGE_OUTPUT");var settings=JsonUtility.FromJson<FaceRecipe>(File.ReadAllText(Path.Combine(output,"FaceSettings.json")));var mesh=RebirthFaceGeneratorModel.Build(data,settings);var request=new FaceImageRequest{stage="lining",reference="C:/Users/Etienne/Downloads/Woman.png",vertices=mesh.vertices.SelectMany(v=>new[]{v.x,v.y,v.z}).ToArray(),uv=mesh.uv.SelectMany(v=>new[]{v.x,v.y}).ToArray(),foundationUv=mesh.uv2.SelectMany(v=>new[]{v.x,v.y}).ToArray(),liningTriangles=mesh.GetTriangles(4)};File.WriteAllText(Path.Combine(output,"request.json"),JsonUtility.ToJson(request));UnityEngine.Object.DestroyImmediate(mesh);Debug.Log("REBIRTH_LINING_REQUEST_READY");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  public static void UpdateSavedLining(){try{string output=Environment.GetEnvironmentVariable("REBIRTH_FACE_IMAGE_OUTPUT");var settings=JsonUtility.FromJson<FaceRecipe>(File.ReadAllText(Path.Combine(output,"FaceSettings.json")));var material=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(settings.generatedLiningMaterialGuid));string path=AssetDatabase.GetAssetPath(material.mainTexture);File.Copy(Path.Combine(output,"MouthLiningAlbedo.png"),path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);AssetDatabase.SaveAssets();RenderSaved();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  public static void RenderSaved(){try{
   template=RebirthFaceGeneratorWindow.ReadTemplate();string output=Environment.GetEnvironmentVariable("REBIRTH_FACE_IMAGE_OUTPUT");var recipe=JsonUtility.FromJson<FaceRecipe>(File.ReadAllText(Path.Combine(output,"FaceSettings.json")));recipe.Validate(template);
   var skin=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(recipe.generatedMaterialGuid));var eye=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(recipe.generatedEyeMaterialGuid));var oral=RebirthFaceGeneratorWindow.CreateOralMaterials(recipe);var mesh=RebirthFaceGeneratorModel.Build(template,recipe);if(Environment.GetEnvironmentVariable("REBIRTH_FACE_NO_REFLECTIONS")=="1"){skin=new Material(skin);skin.SetFloat("_GlossyReflections",0);skin.EnableKeyword("_GLOSSYREFLECTIONS_OFF");}if(Environment.GetEnvironmentVariable("REBIRTH_FACE_CLAY")=="1"){skin=new Material(Shader.Find("Standard"));skin.color=Color.gray;skin.SetFloat("_Glossiness",.1f);eye=new Material(skin);foreach(var part in oral){part.mainTexture=null;part.color=Color.gray;}}var preview=new PreviewRenderUtility();
   try{foreach(int angle in new[]{0,30,90}){preview.BeginStaticPreview(new Rect(0,0,1024,1024));RebirthFaceGeneratorWindow.ConfigurePreview(preview,new Vector2(angle,0),.19f/Mathf.Max(.3f,recipe.portraitScale),false,recipe);if(Environment.GetEnvironmentVariable("REBIRTH_FACE_MOUTH_CLOSEUP")=="1"){var cavity=mesh.GetTriangles(4).Distinct().Select(i=>mesh.vertices[i]).ToArray();var center=new Vector3((cavity.Min(v=>v.x)+cavity.Max(v=>v.x))*.5f,(cavity.Min(v=>v.y)+cavity.Max(v=>v.y))*.5f,.13f);preview.camera.orthographicSize=.045f;preview.camera.transform.position=center+Quaternion.Euler(0,angle,0)*Vector3.forward*2;preview.camera.transform.LookAt(center);}if(Environment.GetEnvironmentVariable("REBIRTH_FACE_BACKGROUND_CHECK")=="1"){preview.camera.clearFlags=CameraClearFlags.SolidColor;preview.camera.backgroundColor=Color.magenta;}preview.DrawMesh(mesh,Matrix4x4.identity,skin,0);preview.DrawMesh(mesh,Matrix4x4.identity,eye,1);RebirthFaceGeneratorWindow.DrawOral(preview,mesh,oral);preview.Render();var image=preview.EndStaticPreview();File.WriteAllBytes(Path.Combine(output,"UnityMouth_"+angle+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}}
   finally{preview.Cleanup();UnityEngine.Object.DestroyImmediate(mesh);foreach(var m in oral)UnityEngine.Object.DestroyImmediate(m);}
   if(Environment.GetEnvironmentVariable("REBIRTH_FACE_BACKGROUND_CHECK")!="1"&&Environment.GetEnvironmentVariable("REBIRTH_FACE_MOUTH_CLOSEUP")!="1")RebirthFaceGeneratorWindow.Export(template,recipe,"Assets/PortraitExample.prefab",skin);Debug.Log("REBIRTH_MOUTH_RENDER_READY");EditorApplication.Exit(0);
  }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
  static void Poll(){try{
   if((DateTime.UtcNow-started).TotalMinutes>8)throw new TimeoutException("Portrait generation exceeded eight minutes.");job.Poll();if(!job.Finished)return;if(job.Error!=null)throw new Exception(job.Error);
   string output=Environment.GetEnvironmentVariable("REBIRTH_FACE_IMAGE_OUTPUT");if(string.IsNullOrEmpty(output))throw new Exception("Artifact output folder missing.");Directory.CreateDirectory(output);
   foreach(string file in Directory.GetFiles(job.Folder)){if(Path.GetFileName(file)=="request.json")continue;File.Copy(file,Path.Combine(output,Path.GetFileName(file)),true);}
   File.WriteAllText(Path.Combine(output,"FaceSettings.json"),JsonUtility.ToJson(job.Candidate,true));
   var mesh=RebirthFaceGeneratorModel.Build(template,job.Candidate);var eye=new Material(AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(job.Candidate.generatedEyeMaterialGuid)));var oral=RebirthFaceGeneratorWindow.CreateOralMaterials(job.Candidate);var preview=new PreviewRenderUtility();
   try{foreach(int angle in new[]{0,30,90,150,180}){preview.BeginStaticPreview(new Rect(0,0,1024,1024));RebirthFaceGeneratorWindow.ConfigurePreview(preview,new Vector2(angle,0),.19f/Mathf.Max(.3f,job.Candidate.portraitScale),false,job.Candidate);preview.DrawMesh(mesh,Matrix4x4.identity,job.CandidateMaterial,0);preview.DrawMesh(mesh,Matrix4x4.identity,eye,1);RebirthFaceGeneratorWindow.DrawOral(preview,mesh,oral);preview.Render();var image=preview.EndStaticPreview();File.WriteAllBytes(Path.Combine(output,"UnityPortrait_"+angle+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}}
   finally{preview.Cleanup();UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(eye);foreach(var m in oral)UnityEngine.Object.DestroyImmediate(m);}
   RebirthFaceGeneratorWindow.Export(template,job.Candidate,"Assets/PortraitExample.prefab",job.CandidateMaterial);Debug.Log("REBIRTH_FACE_IMAGE_EXAMPLE_READY");EditorApplication.update-=Poll;job.Dispose();EditorApplication.Exit(0);
  }catch(Exception e){EditorApplication.update-=Poll;if(job!=null)job.Dispose();Debug.LogException(e);EditorApplication.Exit(1);}}
 }
}
